SELECT 
FROM equip_asset
WHERE is_deleted = 0

    AND (equip_name LIKE CONCAT('%', #{keyword}, '%')
         OR equip_code LIKE CONCAT('%', #{keyword}, '%')
         OR serial_no LIKE CONCAT('%', #{keyword}, '%'))


    AND status = #{status}


    AND category_id = #{categoryId}


    AND production_line = #{productionLine}

ORDER BY id DESC
LIMIT #{offset}, #{limit}

SELECT COUNT(*)
FROM equip_asset
WHERE is_deleted = 0

    AND (equip_name LIKE CONCAT('%', #{keyword}, '%')
         OR equip_code LIKE CONCAT('%', #{keyword}, '%')
         OR serial_no LIKE CONCAT('%', #{keyword}, '%'))


    AND status = #{status}


    AND category_id = #{categoryId}


    AND production_line = #{productionLine}
